package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class LmdbTupleFunctionDependencyRegressionTest {
	@TempDir
	Path directory;

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void tupleDependenciesUseActualRowBindingsInBothEvaluators(boolean nativeEvaluation) {
		SailRepository memory = new SailRepository(new MemoryStore());
		SailRepository lmdb = new SailRepository(new LmdbStore(directory.toFile(),
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(nativeEvaluation)));
		try {
			for (String calls : List.of(
					"(?x 2) arrf:generateSeries ?y . (?y 2) arrf:generateSeries ?x",
					"(?y 2) arrf:generateSeries ?x . (?x 2) arrf:generateSeries ?y")) {
				String body = "VALUES (?x ?y) {(1 UNDEF) (UNDEF 2)} " + calls;
				assertEquals(List.of("1,1", "2,2"), rows(memory, body));
				assertEquals(List.of("1,1", "2,2"), rows(lmdb, body));
			}
			String undef = "VALUES ?x {UNDEF} (?x 2) arrf:generateSeries ?y . "
					+ "(1 2) arrf:generateSeries ?x";
			assertEquals(List.of("1,1", "1,2", "2,2"), rows(memory, undef));
			assertEquals(List.of("1,1", "1,2", "2,2"), rows(lmdb, undef));
			String duplicates = "VALUES ?seed {1 1} (1 2) arrf:generateSeries ?x . "
					+ "(1 2) arrf:generateSeries ?y";
			List<String> bag = List.of("1,1", "1,1", "1,2", "1,2", "2,1", "2,1", "2,2", "2,2");
			assertEquals(bag, rows(memory, duplicates));
			assertEquals(bag, rows(lmdb, duplicates));
			String external = "(?start 2) arrf:generateSeries ?x . (?x 2) arrf:generateSeries ?y";
			assertEquals(List.of("1,1", "1,2", "2,2"), rows(memory, external, true));
			assertEquals(List.of("1,1", "1,2", "2,2"), rows(lmdb, external, true));
		} finally {
			lmdb.shutDown();
			memory.shutDown();
		}
	}

	private static List<String> rows(SailRepository repository, String body) {
		return rows(repository, body, false);
	}

	private static List<String> rows(SailRepository repository, String body, boolean bindStart) {
		try (var connection = repository.getConnection()) {
			var query = connection.prepareTupleQuery("""
					PREFIX arrf: <http://rdf4j.org/function/array#>
					SELECT ?x ?y WHERE {
					""" + body + "} ORDER BY ?x ?y");
			if (bindStart) {
				query.setBinding("start", SimpleValueFactory.getInstance().createLiteral(1));
			}
			try (var result = query.evaluate()) {
				List<String> rows = new ArrayList<>();
				while (result.hasNext()) {
					var row = result.next();
					rows.add(row.getValue("x").stringValue() + "," + row.getValue("y").stringValue());
				}
				return rows;
			}
		}
	}
}
